// Builds the demo site's generated files:
//   docs/data.js    from the recorded runs in data/runs/
//   docs/engine.js  the REAL judge, gate, scenarios and prompt renderer (src/*.ts) compiled to one
//                   browser module, so the site runs the same code as the tests and live runs.
//   node scripts/build-site.mjs          (TSC=/path/to/tsc to override "npx tsc")

import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

execFileSync(process.execPath, ["src/site/build-data.ts"], { stdio: "inherit" });

const out = mkdtempSync(join(tmpdir(), "crashcart-"));
const tsc = process.env.TSC ? [process.env.TSC] : ["npx", "tsc"];
const sources = ["src/core/judge.ts", "src/core/gate.ts", "src/scenarios/index.ts", "src/scenarios/level2.ts", "src/agent/shopper.ts"];
execFileSync(
  tsc[0],
  [...tsc.slice(1), "--ignoreConfig", "--outDir", out, "--rootDir", "src", "--module", "ESNext", "--target", "ES2022", "--moduleResolution", "Bundler", "--rewriteRelativeImportExtensions", "--skipLibCheck", "--strict", ...sources],
  { stdio: "inherit" }
);

const order = ["scenarios/index.js", "scenarios/level2.js", "core/judge.js", "core/gate.js", "agent/shopper.js"];
const all = [];
const chunks = order.map((file) => {
  const names = [];
  const body = readFileSync(join(out, file), "utf8")
    .replace(/^import .*$/gm, "")
    .replace(/^export \{\};?\s*$/gm, "")
    .replace(/^export (const|let|function) (\w+)/gm, (_m, kw, n) => {
      names.push(n);
      return `${kw} ${n}`;
    });
  all.push(...names);
  // Each module keeps its own scope so private names (EPS, MERCHANT...) cannot collide.
  return `// --- ${file} ---\nconst { ${names.join(", ")} } = (() => {\n${body}\nreturn { ${names.join(", ")} };\n})();`;
});
writeFileSync(
  "docs/engine.js",
  `// GENERATED by scripts/build-site.mjs from src/. Do not edit by hand.\n${chunks.join("\n\n")}\n\nexport { ${all.join(", ")} };\n`
);
rmSync(out, { recursive: true, force: true });
console.log(`docs/engine.js: ${all.length} exports (${all.join(", ")})`);
